import { Group, Mesh, PlaneGeometry, BoxGeometry, Color, AmbientLight, DirectionalLight, PointLight, RepeatWrapping, LinearFilter, MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, vec4, mix, smoothstep, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? {};
  const imageUrl = config.imageUrl;

  const accentHex = colors.accent ?? '#ff2a38';
  const inkHex = colors.ink ?? '#16161d';
  const paperHex = colors.paper ?? '#e8ecf2';
  const bgHex = colors.background ?? '#0b0b10';
  const surfHex = colors.surface ?? '#14141a';

  const root = new Group();
  root.name = 'loop-column-gallery';

  const cleanups = [];
  const disposeList = [];

  // ---- Backdrop gradient stage (never void) ----
  const backdropGeo = new PlaneGeometry(8, 7);
  disposeList.push(backdropGeo);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(vec3(new Color(bgHex).r, new Color(bgHex).g, new Color(bgHex).b), vec3(new Color(surfHex).r, new Color(surfHex).g, new Color(surfHex).b), uv().y);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposeList.push(backdropMat);

  // Subtle red atmosphere plane behind column for depth
  const atmosGeo = new PlaneGeometry(3.4, 6.4);
  disposeList.push(atmosGeo);
  const atmosMat = new MeshBasicNodeMaterial();
  atmosMat.colorNode = mix(vec3(0.02, 0.0, 0.0), vec3(0.0, 0.0, 0.0), smoothstep(0.0, 1.0, uv().y));
  atmosMat.transparent = true;
  const atmos = new Mesh(atmosGeo, atmosMat);
  atmos.position.set(0.9, 0, -2.2);
  root.add(atmos);
  disposeList.push(atmosMat);

  // ---- Lighting (local rim/accent) ----
  const ambient = new AmbientLight(0xffffff, 0.45);
  root.add(ambient);
  const keyLight = new DirectionalLight(0xffffff, 1.1);
  keyLight.position.set(-2.2, 2.6, 3.0);
  root.add(keyLight);
  const rim = new DirectionalLight(new Color(accentHex), 0.7);
  rim.position.set(3.0, -1.0, -1.8);
  root.add(rim);
  const fill = new PointLight(0x6a7080, 0.4, 12, 1.5);
  fill.position.set(-2.5, 0.5, 2.0);
  root.add(fill);

  // ---- Column ----
  const column = new Group();
  root.add(column);

  const PLATE_W = 1.9, PLATE_H = 1.2, PITCH = 1.5, N = 6, LOOP = 9.0, COL_X = 0.9;

  const plates = [];
  const captions = [];
  const accentMats = [];

  // Headline (pinned, left column)
  const headlineItem = items.find(i => i.role === 'headline');
  const headlineText = headlineItem?.text ?? 'Inside the atelier';
  const headline = ctx.fontAtlas.createText(headlineText, { fontSize: 68, color: paperHex, align: 'left' });
  headline.position.set(-1.6, 1.9, 0);
  root.add(headline);

  // Subtitle micro-label under headline
  const microLabel = ctx.fontAtlas.createText('NOVA ATELIER  /  THE INDEX', { fontSize: 16, color: accentHex, align: 'left', letterSpacingPx: 1.9 });
  microLabel.position.set(-1.6, 2.35, 0);
  root.add(microLabel);

  const captionItems = items.filter(i => i.role === 'caption');
  const captionStrings = captionItems.map(i => i.text);

  const inkColor = new Color(inkHex);

  for (let i = 0; i < N; i++) {
    const pg = new Group();
    column.add(pg);

    // machined ink bevel frame
    const frameGeo = new BoxGeometry(PLATE_W + 0.08, PLATE_H + 0.08, 0.05);
    disposeList.push(frameGeo);
    const frameMat = new MeshPhysicalNodeMaterial();
    frameMat.color = inkColor;
    frameMat.roughness = 0.5;
    frameMat.metalness = 0.5;
    frameMat.clearcoat = 0.25;
    const frame = new Mesh(frameGeo, frameMat);
    frame.position.set(COL_X, 0, -0.03);
    pg.add(frame);
    disposeList.push(frameMat);

    // brushed edge highlight (thin inner border plane)
    const edgeGeo = new PlaneGeometry(PLATE_W + 0.04, PLATE_H + 0.04);
    disposeList.push(edgeGeo);
    const edgeMat = new MeshBasicNodeMaterial();
    edgeMat.colorNode = vec3(0.32, 0.33, 0.36);
    edgeMat.transparent = true;
    edgeMat.opacity = 0.5;
    const edge = new Mesh(edgeGeo, edgeMat);
    edge.position.set(COL_X, 0, -0.005);
    pg.add(edge);
    disposeList.push(edgeMat);

    // photo plate
    const plateGeo = new PlaneGeometry(PLATE_W, PLATE_H);
    disposeList.push(plateGeo);
    const plateMat = new MeshPhysicalNodeMaterial();
    plateMat.color = new Color(0x202028);
    plateMat.roughness = 0.6;
    plateMat.metalness = 0.1;
    plateMat.clearcoat = 0.1;
    const plate = new Mesh(plateGeo, plateMat);
    plate.position.set(COL_X, 0, 0.012);
    pg.add(plate);
    disposeList.push(plateMat);

    // accent strip (left edge), emissive feel via bright basic material
    const accentGeo = new PlaneGeometry(0.03, PLATE_H + 0.04);
    disposeList.push(accentGeo);
    const accentMat = new MeshBasicNodeMaterial();
    accentMat.colorNode = vec3(new Color(accentHex).r, new Color(accentHex).g, new Color(accentHex).b).mul(1.4);
    accentMat.transparent = true;
    accentMat.opacity = 0;
    const accent = new Mesh(accentGeo, accentMat);
    accent.position.set(COL_X - PLATE_W / 2 - 0.015, 0, 0.02);
    pg.add(accent);
    disposeList.push(accentMat);

    const baseY = (i - (N - 1) / 2) * PITCH;
    plates.push({ group: pg, mat: plateMat, frameMat, baseY, idx: i });
    accentMats.push(accentMat);

    // caption (left column, moves with column, synced to focused plate y)
    const capStr = captionStrings[i] ?? '';
    const cap = ctx.fontAtlas.createText(capStr, { fontSize: 18, color: paperHex, align: 'left', letterSpacingPx: 1.44 });
    cap.position.set(-1.6, baseY, 0.05);
    cap.visible = false;
    column.add(cap);
    captions.push(cap);
  }

  // ---- Load photo texture and bake distinct crops + vignette ----
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      tex.wrapS = tex.wrapT = RepeatWrapping;
      tex.minFilter = tex.magFilter = LinearFilter;
      tex.needsUpdate = true;
      for (let i = 0; i < N; i++) {
        const repY = 1 / 6;
        const offY = i / 6;
        const texNode = texture(tex, uv().mul(vec2(1, repY)).add(vec2(0, offY)));
        const d = uv().sub(0.5).length().mul(1.7);
        const vignette = smoothstep(0.42, 0.66, d);
        const p = plates[i];
        p.mat.colorNode = mix(texNode.rgb, vec3(0.015, 0.015, 0.02), vignette);
        p.mat.needsUpdate = true;
      }
    });
  }

  // ---- Continuous weighted loop via gsap.ticker ----
  let offset = 0;
  let displayOffset = 0;
  let focused = -1;
  const SPEED = 0.45; // units/sec

  function mod9(v) {
    let m = v % LOOP;
    if (m < 0) m += LOOP;
    return m;
  }

  function setFocus(newIdx, y) {
    if (newIdx === focused) return;
    if (focused >= 0) {
      const op = plates[focused];
      gsap.to(op.group.scale, { x: 1, y: 1, z: 1, duration: 0.45, ease: 'power3.out' });
      gsap.to(accentMats[focused], { opacity: 0, duration: 0.35, ease: 'power2.out' });
      const oc = captions[focused];
      gsap.to(oc.position, { y: y + 0.15, duration: 0.3, ease: 'power2.in', onComplete: () => { oc.visible = false; } });
    }
    focused = newIdx;
    const np = plates[focused];
    gsap.to(np.group.scale, { x: 1.06, y: 1.06, z: 1, duration: 0.35, ease: 'expo.out' });
    gsap.to(accentMats[focused], { opacity: 1, duration: 0.35, ease: 'power2.out' });
    const nc = captions[focused];
    nc.visible = true;
    gsap.fromTo(nc.position, { y: y - 0.12 }, { y: y, duration: 0.5, ease: 'power3.out' });
  }

  function tickFn(dt) {
    offset += SPEED * dt;
    // weighted inertia follow
    displayOffset += (offset - displayOffset) * (1 - Math.exp(-dt / 0.55));

    let best = 0, bestD = Infinity, bestY = 0;
    for (let i = 0; i < N; i++) {
      const p = plates[i];
      let y = mod9(p.baseY - displayOffset);
      if (y > LOOP / 2) y -= LOOP;
      p.group.position.y = y;
      const d = Math.abs(y);
      if (d < bestD) { bestD = d; best = i; bestY = y; }
    }
    // captions: only focused visible & synced
    if (focused >= 0) {
      captions[focused].position.y = plates[focused].group.position.y;
    }
    setFocus(best, bestY);
  }
  gsap.ticker.add(tickFn);

  // ---- Entrance: rise-in for headline + column ----
  const introTl = gsap.timeline();
  introTl.from(headline.position, { y: 1.9 + 0.4, duration: 0.7, ease: 'power3.out' }, 0);
  introTl.from(headline, { ...{} }, 0);
  // opacity fade for headline via scale fallback (fontAtlas text has no opacity proxy guaranteed)
  introTl.from(microLabel.position, { y: 2.35 + 0.2, duration: 0.5, ease: 'power2.out' }, 0.1);
  introTl.from(column.position, { z: 0.4, duration: 0.8, ease: 'power3.out' }, 0);
  introTl.from(column.position, { y: 0.25, duration: 0.8, ease: 'power3.out' }, 0);

  // ---- Apply cinematic primitives ----
  const primCleanups = [];
  const prims = config.cinematicPrimitives ?? [];
  for (const prim of prims) {
    if (prim.name && ctx.primitives && ctx.primitives[prim.name]) {
      try {
        const r = ctx.primitives[prim.name](root, prim.params ?? {});
        if (r && r.cleanup) primCleanups.push(r.cleanup);
      } catch (e) { /* ignore primitive failure */ }
    }
  }

  // ---- Cleanup ----
  root.userData.cleanup = () => {
    gsap.ticker.remove(tickFn);
    introTl.kill();
    gsap.killTweensOf(column.position);
    for (const p of plates) {
      gsap.killTweensOf(p.group.scale);
      gsap.killTweensOf(p.group.position);
    }
    for (const am of accentMats) gsap.killTweensOf(am);
    for (const c of captions) gsap.killTweensOf(c.position);
    for (const c of primCleanups) { try { c(); } catch (e) {} }
    for (const d of disposeList) { try { d.dispose && d.dispose(); } catch (e) {} }
  };

  root.userData.handlers = {};

  return root;
}
